'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>/^https:\/\//.test(s||'')?s:'#';
let saved={favorites:[],notes:{},journal:'',compact:false};
try{saved={...saved,...JSON.parse(localStorage.getItem('stronghold-guide-v1')||'{}')}}catch{}
if(!Array.isArray(saved.favorites))saved.favorites=[];
if(!saved.notes||typeof saved.notes!=='object')saved.notes={};
let page='overview',filter='all';
const headings={overview:['01 / OPERATIONS BRIEF','先选方向，再补齐阵容'],factions:['02 / ALLIANCE DATABASE','八大盟约 · 体系档案'],operators:['03 / OPERATOR INDEX','核心干员 · 按职责查阅'],rounds:['04 / FIELD CHECKLIST','每一轮，都有清晰的取舍'],sources:['05 / INTELLIGENCE LIBRARY','教学资料 · 回到原始出处'],updates:['06 / ARCHIVE MANAGEMENT','版本留痕，思路持续更新']};
function persist(){try{localStorage.setItem('stronghold-guide-v1',JSON.stringify(saved));return true}catch{toast('浏览器存储不可用，请导出笔记备份');return false}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function matches(x,q){return !q||JSON.stringify(x).toLowerCase().includes(q.toLowerCase())}
function currentFactions(){const q=$('#search').value.trim();return GUIDE.factions.filter(f=>matches(f,q)&&(filter!=='favorites'||saved.favorites.includes(f.id)))}
function card(f,i){const on=saved.favorites.includes(f.id);return `<article class="card"><div class="card-top"><span class="card-id">ALLIANCE / ${String(GUIDE.factions.indexOf(f)+1).padStart(2,'0')}</span><button class="favorite ${on?'on':''}" data-fav="${esc(f.id)}" aria-label="${on?'取消收藏':'收藏'}${esc(f.name)}" aria-pressed="${on}">${on?'★':'☆'}</button></div><span class="card-mark">${esc(f.symbol||'◈')}</span><h3>${esc(f.name)}</h3><p class="tagline">${esc(f.tagline)}</p><span class="label">关键干员 / 起手与成型</span><div class="operator-chips">${f.core.slice(0,4).map(n=>`<span>${esc(n)}</span>`).join('')}</div><p class="card-summary">${esc(f.summary||f.plan[0])}</p><div class="card-footer"><span class="tag">机制已核对</span>${saved.notes[f.id]?'<span class="note-indicator">有个人备注</span>':''}<button data-detail="${esc(f.id)}">展开作战档案 ↗</button></div></article>`}
function sourcesHTML(list){return list.map(s=>`<article class="source"><div class="date">${esc(s.date||'日期待核')}<br><span class="tag ${s.kind==='视频'?'gold':''}">${esc(s.kind||'资料')}</span></div><div><h3>${esc(s.title)}</h3><span class="label">${esc(s.author||'')} · ${esc(s.scope||'原版攻略参考')}</span><p>${esc(s.summary)}</p>${s.caution?`<p>注意：${esc(s.caution)}</p>`:''}</div><a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener">查看原文 ↗</a></article>`).join('')}
function render(){const q=$('#search').value.trim();$('#section-code').textContent=headings[page][0];$('#section-title').textContent=headings[page][1];document.body.classList.toggle('page-other',page!=='overview');document.body.classList.toggle('compact',!!saved.compact);$('#compact').setAttribute('aria-pressed',!!saved.compact);$('#compact').textContent=saved.compact?'标准视图':'紧凑视图';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#filters').innerHTML=(page==='overview'||page==='factions')?`<button data-filter="all" class="${filter==='all'?'active':''}">全部体系 · 08</button><button data-filter="favorites" class="${filter==='favorites'?'active':''}">★ 我的收藏 · ${saved.favorites.length}</button><span class="label" style="align-self:center;margin-left:auto">点开档案查看机制、运营与注意事项</span>`:page==='sources'?['all','视频','官方更新','仓库'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t==='all'?'全部资料':t}</button>`).join(''):'';
let html='';
if(page==='overview'||page==='factions'){const fs=currentFactions();html=fs.length?`<div class="cards">${fs.map(card).join('')}</div>`:'<div class="empty">没有找到匹配的体系。试试干员名字，或切换“全部体系”。</div>';if(page==='overview'&&!q&&filter==='all')html+=`<h3 class="section-subtitle">出发前，记住三件事 <span class="label">/ QUICK CHECK</span></h3><div class="quick-grid"><a class="quick" href="#rounds"><b>01 / PLAN</b><h3>先看禁用，再定路线</h3><p>确认本局盟约、敌方类型和领袖。关键件被禁时，换一条能持续叠层的路线。</p></a><a class="quick" href="#operators"><b>02 / BUILD</b><h3>叠层件与输出位分工</h3><p>提供成长的干员不一定负责清场。保留发动机，再补输出、生存和对空能力。</p></a><a class="quick" href="#sources"><b>03 / VERIFY</b><h3>学思路，也看版本</h3><p>3 月教程包含更新前阵容。按当前移植版核对费用、阈值与技能，再复现运营。</p></a></div>`}
if(page==='operators'){const rows=GUIDE.operators||GUIDE.factions.flatMap(f=>f.core.map(name=>({name,faction:f.name,factionId:f.id,role:'该体系关键候选；具体选取随来牌与禁用调整。'})));html=rows.filter(x=>matches(x,q)).map(o=>`<article class="operator-row"><h3>${esc(o.name)}</h3><span class="tag">${esc(o.faction)}</span><p>${esc(o.role)}</p><button data-detail="${esc(o.factionId)}">查看体系 ↗</button></article>`).join('')||'<div class="empty">没有匹配的干员。</div>'}
if(page==='rounds'){html=`<div class="notice" style="margin-bottom:20px"><span>i</span><p>以下为基于规则的通用决策顺序。具体升本回合因策略、来牌和血量而变，不是一套固定操作表。</p></div>`+GUIDE.rounds.filter(x=>matches(x,q)).map((r,i)=>`<article class="timeline-item"><div class="step">${esc(r.number||String(i).padStart(2,'0'))}</div><div><span class="label">${esc(r.phase)}</span><h3>${esc(r.title)}</h3>${r.points.map(p=>`<p>— ${esc(p)}</p>`).join('')}</div></article>`).join('');html+=`<h3 class="section-subtitle">机制速记</h3><div class="quick-grid">${(GUIDE.mechanics||[]).filter(x=>matches(x,q)).map(m=>`<div class="quick"><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p></div>`).join('')}</div>`}
if(page==='sources'){const rows=GUIDE.sources.filter(s=>matches(s,q)&&(filter==='all'||filter===s.kind));html=`<div class="notice" style="margin-bottom:20px"><span>i</span><p>视频摘要来自可读取的页面标题、简介或文字攻略，未逐帧观看；不将标题中的通关或伤害表现视为本站实测。</p></div>`+(sourcesHTML(rows)||'<div class="empty">没有匹配的资料。</div>')}
if(page==='updates'){html=`<section class="update-panel"><span class="eyebrow">VERSION BASELINE</span><h3>当前内容基线 · ${esc(GUIDE.version)}</h3><p>核对日期：2026-10-19 · 原版资料重点：2026 年 3 月。移植版未启用改变规则的玩法插件。</p><p>仓库提交 <span class="inline-code">${esc(GUIDE.commit)}</span></p><p>官方在 2026-03-27 的更新调整了玩法内容。此前视频可用于学习体系，但阈值、等阶和运营节奏需要对照当前仓库。本站的“机制已核对”指源码审查，不代表完成了整局实测。</p><a class="source-link" href="https://github.com/sganggs/Stronghold-Protocol/commit/${esc(GUIDE.commit)}" target="_blank" rel="noopener">查看对应提交 ↗</a></section><section class="update-panel"><h3>我的对局手记</h3><p>记录来牌、策略、失败原因和下次调整。笔记与收藏仅保存在当前浏览器，可导出后转移到手机或平板。</p><textarea id="journal" aria-label="对局手记" placeholder="例如：第 7 回合缺对空，下次先补远程位，再考虑升本。">${esc(saved.journal)}</textarea><div class="action-row"><button id="save-journal">保存手记</button><button id="export-notes">导出笔记与收藏</button><button id="import-notes">导入备份</button><input id="import-file" class="hidden" type="file" accept="application/json,.json"></div><p id="import-status" role="status"></p></section><section class="update-panel"><h3>为下一次版本更新留好位置</h3><p>攻略与界面分离：data.js 保存盟约、核心干员、运营与出处；网页样式独立。更新时替换对应条目、修改版本和提交号，并补上来源，即可继续使用现有界面。</p><p>建议维护顺序：版本差异 → 盟约阈值与干员特质 → 阵容思路 → 教学链接。个人备注不会被网站内容更新覆盖。</p><div class="action-row"><button id="export-content">导出当前攻略数据</button><a class="button" href="data.js" download>下载数据源 ↗</a></div></section>`}
if(page==='factions'&&filter==='all'){const addons=(GUIDE.addons||[]).filter(a=>matches(a,q));if(addons.length)html+=`<h3 class="section-subtitle">附加盟约 · 补齐你的体系 <span class="label">/ SUPPORTING ALLIANCES</span></h3><div class="quick-grid">${addons.map(a=>`<article class="quick"><b>${esc(a.disabledInStandard?'险境及以上':'标准可用')}</b><h3>${esc(a.name)}</h3><p>${esc(a.summary)}</p><p style="margin-top:12px">成员：${esc(a.members.length?a.members.join(' / '):'按在场精锐总数计数')}</p></article>`).join('')}</div>`}
$('#content').innerHTML=html;bindContent();}
function bindContent(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{const id=b.dataset.fav;saved.favorites=saved.favorites.includes(id)?saved.favorites.filter(x=>x!==id):[...saved.favorites,id];persist();render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});if(page==='updates'){$('#save-journal').onclick=()=>{saved.journal=$('#journal').value;if(persist())toast('对局手记已保存')};$('#export-notes').onclick=()=>{saved.journal=$('#journal').value;persist();download('stronghold-notes.json',{schema:1,...saved})};$('#export-content').onclick=()=>download('stronghold-guide-content.json',GUIDE);$('#import-notes').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('文件过大');const d=JSON.parse(await f.text());if(d.schema!==1||!Array.isArray(d.favorites)||!d.notes||typeof d.notes!=='object'||Array.isArray(d.notes)||typeof d.journal!=='string'||Object.values(d.notes).some(x=>typeof x!=='string'))throw Error('不是有效的笔记备份');saved.favorites=[...new Set([...saved.favorites,...d.favorites.filter(id=>GUIDE.factions.some(f=>f.id===id))])];for(const [id,note]of Object.entries(d.notes)){if(!GUIDE.factions.some(f=>f.id===id))continue;saved.notes[id]=saved.notes[id]&&saved.notes[id]!==note?saved.notes[id]+'\n\n[导入的笔记]\n'+note:note}if(d.journal&&saved.journal!==d.journal)saved.journal=[saved.journal,d.journal].filter(Boolean).join('\n\n[导入的手记]\n');persist();render();toast('已合并导入，原有笔记保留')}catch(err){$('#import-status').textContent='导入失败：'+err.message} }} }
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openDetail(id){const f=GUIDE.factions.find(x=>x.id===id);if(!f)return;$('#detail-content').innerHTML=`<div class="detail-head"><div><div class="eyebrow">ALLIANCE DOSSIER / ${esc(f.id)}</div><h2>${esc(f.name)}</h2><p class="detail-tagline">${esc(f.tagline)}</p></div><button class="close" aria-label="关闭档案">×</button></div><div class="detail-block"><h3>01 / 机制与启动条件 <span class="tag">源码核对</span></h3><p>${esc(f.trigger)}</p>${f.thresholds?`<p>${esc(f.thresholds)}</p>`:''}</div><div class="detail-block"><h3>02 / 核心与职责</h3><div class="operator-chips">${f.core.map(n=>`<span>${esc(n)}</span>`).join('')}</div>${(f.coreDetails||[]).map(x=>`<p>${esc(typeof x==='string'?x:JSON.stringify(x))}</p>`).join('')}</div><div class="detail-block"><h3>03 / 运营思路 <span class="tag gold">规则推导 / 非实测</span></h3><ol>${f.plan.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="detail-block"><h3>04 / 关键提醒</h3><ul>${f.pitfalls.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${(f.teaching||[]).length?`<div class="detail-block"><h3>05 / 对照教学</h3>${sourcesHTML(f.teaching)}</div>`:''}<div class="detail-block"><h3>个人备注</h3><textarea class="notes" id="faction-note" aria-label="${esc(f.name)}个人备注" placeholder="记下自己的阵容变体、装备选择或失误点…">${esc(saved.notes[id]||'')}</textarea><div class="action-row"><button id="save-note">保存本体系备注</button></div></div><div class="detail-evidence">对应 ${esc(GUIDE.version)} / ${esc(GUIDE.commit.slice(0,7))}<br>${f.sourcePaths.map(p=>`<a class="source-link" href="https://github.com/sganggs/Stronghold-Protocol/blob/${esc(GUIDE.commit)}/${esc(p)}" target="_blank" rel="noopener">${esc(p)} ↗</a>`).join('<br>')}</div>`;$('#detail .close').onclick=()=>$('#detail').close();$('#save-note').onclick=()=>{saved.notes[id]=$('#faction-note').value;if(persist()){toast('体系备注已保存');render()}};$('#detail').showModal();$('#detail').scrollTop=0}
function route(){const next=location.hash.slice(1);page=headings[next]?next:'overview';filter='all';$('#search').value='';render()}
window.addEventListener('hashchange',route);$('#search').addEventListener('input',render);$('#compact').onclick=()=>{saved.compact=!saved.compact;persist();render()};$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#search').focus()}});$('#version-label').textContent='WEB / '+GUIDE.version;$('#baseline').textContent='v'+GUIDE.version;route();

